def transform(grid):
    """Fill background cells with 2 when BOTH left AND right neighbors are minority"""
    # Make a copy
    result = [row[:] for row in grid]

    # Find minority color in input
    from collections import Counter
    counts = Counter()
    for row in result:
        for x in row:
            counts[x] += 1
    if len(counts) < 2:
        return result
    min_color = min(counts, key=counts.get)
    bg_color = max(counts, key=counts.get)  # background is majority

    # Apply transform: fill bg cells where BOTH neighbors are minority
    for row_idx, row in enumerate(result):
        for c in range(len(row)):
            if result[row_idx][c] == bg_color:
                left_is_minority = (c > 0 and result[row_idx][c-1] == min_color)
                right_is_minority = (c < len(row) - 1 and result[row_idx][c+1] == min_color)
                if left_is_minority and right_is_minority:
                    result[row_idx][c] = 2
    return result

